<script>
  import { resolve } from '$app/paths';
  import { language } from '#lib/stores/language.js';
  import PublicStudyEvidence from '#lib/components/PublicStudyEvidence.svelte';
  import GameBatchLab from '#lib/components/GameBatchLab.svelte';
  $: t = $language === 'en' ? (/** @type {string} */ fr, /** @type {string} */ en) => en : (/** @type {string} */ fr, /** @type {string} */ en) => fr;
  // Each pair is French / English. Cases teach design and interpretation; no numerical study results are fabricated.
  const paths = [
    {name:'Airway', title:['Transcriptomique : du plan au résultat','Transcriptomics: from design to results'], steps:[
      {q:['Des cellules provenant de mêmes donneurs sont mesurées avec et sans dexaméthasone. Quel plan retenir ?','Cells from the same donors are measured with and without dexamethasone. Which design is appropriate?'], a:[['Groupes indépendants','Independent groups'],['Comparaison appariée par donneur','Donor-paired comparison']],correct:1,why:['Le donneur est un bloc : ignorer l’appariement confond la variabilité inter-donneurs et l’effet du traitement.','Donor is a block: ignoring pairing conflates between-donor variation and treatment effects.']},
      {q:['Que faut-il vérifier avant une analyse différentielle RNA-seq ?','What should be checked before RNA-seq differential analysis?'],a:[['Correspondance des échantillons, comptages et plan d’étude','Sample alignment, counts and study design'],['Seulement les gènes les plus abondants','Only the most abundant genes']],correct:0,why:['Les colonnes doivent correspondre aux métadonnées et le modèle doit être adapté aux comptages et au plan.','Columns must match metadata, and the model must suit counts and design.']},
      {q:['Une ACP sépare visuellement les groupes. Cela suffit-il à prouver un effet significatif ?','A PCA visually separates groups. Does this prove a significant effect?'],a:[['Oui','Yes'],['Non, il faut une inférence adaptée','No, appropriate inference is needed']],correct:1,why:['L’ACP décrit la variance ; elle ne teste pas l’effet du traitement.','PCA describes variance; it does not test the treatment effect.']},
      {q:['Des milliers de gènes sont testés. Quel résultat faut-il considérer avec l’amplitude d’effet ?','Thousands of genes are tested. What should be considered alongside effect size?'],a:[['P-value brute uniquement','Raw p-value only'],['P-value ajustée pour tests multiples','Multiple-testing-adjusted p-value']],correct:1,why:['La correction BH vise le contrôle du taux de fausses découvertes sous ses hypothèses ; l’effet et son incertitude restent essentiels.','BH adjustment aims to control false discovery rate under its assumptions; effect size and uncertainty remain essential.']}
    ]},
    {name:'Nutrimouse',title:['Multi-omiques : intégrer et interpréter','Multi-omics: integrate and interpret'],steps:[
      {q:['Des mesures transcriptomiques et lipidiques concernent les mêmes souris. Comment les relier ?','Transcript and lipid measurements concern the same mice. How should they be linked?'],a:[['Par identifiant unique de souris','By unique mouse identifier'],['Par ordre des colonnes sans vérification','By column order without checking']],correct:0,why:['Un appariement erroné crée des associations artificielles entre les couches.','Incorrect matching creates artificial cross-layer associations.']},
      {q:['Les matrices ont des unités et dimensions différentes. Quelle précaution prendre ?','Matrices have different units and dimensions. What precaution is needed?'],a:[['Concaténer sans préparation','Concatenate without preparation'],['Prétraiter chaque couche et évaluer son poids','Preprocess each layer and assess its weight']],correct:1,why:['Une couche à variance ou dimension dominante peut masquer les autres ; le choix de mise à l’échelle doit être explicite.','A high-variance or high-dimensional layer can dominate; scaling choices must be explicit.']},
      {q:['Quel outil correspond à la recherche non supervisée de facteurs latents partagés ?','Which tool addresses unsupervised discovery of shared latent factors?'],a:[['MOFA','MOFA'],['DIABLO supervisé','Supervised DIABLO']],correct:0,why:['MOFA est non supervisé ; DIABLO utilise les classes pour sélectionner des signatures discriminantes.','MOFA is unsupervised; DIABLO uses class labels to select discriminative signatures.']},
      {q:['Une signature DIABLO discrimine les régimes sur les données d’apprentissage. Que vérifier ?','A DIABLO signature discriminates diets in training data. What should be checked?'],a:[['La performance hors apprentissage, sans fuite de données','Out-of-training performance without data leakage'],['Seulement la séparation sur les données d’apprentissage','Only training-set separation']],correct:0,why:['La sélection et le réglage doivent rester dans les plis d’apprentissage. Une association prédictive ne démontre pas une causalité.','Feature selection and tuning must stay within training folds. Predictive association does not establish causality.']}
    ]},
    {"name":"Interpretation","title":["Interpréter les résultats","Interpret results"],"steps":[{"q":["Quels gènes sont déclarés significatifs lorsque le seuil BH passe de 0,05 à 0,01 ?","What happens to the number of discoveries when the BH threshold changes from 0.05 to 0.01?"],"a":[["Moins de découvertes, sans réestimation du modèle","Fewer discoveries, without refitting"],["Les effets des gènes diminuent","Gene effect sizes decrease"],["Tous les faux positifs disparaissent","All false positives disappear"]],"correct":0,"why":["Le seuil filtre les q-values déjà estimées : 4 100 puis 2 940 découvertes. Cela ne modifie ni les effets estimés ni les q-values, et ne garantit pas zéro faux positif.","The threshold filters existing adjusted p-values: 4,100 then 2,940 discoveries. It does not change estimated effects or adjusted p-values, and does not guarantee zero false positives."]},{"q":["Que permet de conclure le log2FC ajusté positif de CRISPLD2 (2,630) ?","What does the positive fitted CRISPLD2 log2FC (2.630) establish?"],"a":[["L'effet biologique est cliniquement utile","The effect is clinically useful"],["Dans ce contraste, l'expression estimée est plus élevée sous dexaméthasone","In this contrast, estimated expression is higher under dexamethasone"],["Chaque cellule augmente exactement de la même quantité","Every cell increases by exactly the same amount"]],"correct":1,"why":["2^2,630 ≈ 6,19 : rapport estimé du contraste après modélisation, pas moyenne des rapports bruts, ni effet individuel, ni preuve clinique.","2^2.630 ≈ 6.19: a fitted contrast ratio, not the mean of raw ratios, an individual effect, or clinical evidence."]},{"q":["Dans le scénario fictif où groupe et lot sont confondus, quelle conclusion est défendable ?","In the fictional scenario where group and batch are confounded, which conclusion is defensible?"],"a":[["La séparation prouve un effet biologique","Separation proves a biological effect"],["Il suffit d'ajouter une covariable pour identifier l'effet","Adding a covariate is enough to identify the effect"],["Le plan ne permet pas de séparer les deux effets","The design cannot distinguish the two effects"]],"correct":2,"why":["Si groupe et lot coïncident, les colonnes du modèle sont colinéaires. Une séparation visuelle n'identifie pas l'origine du signal ; il faut des groupes représentés dans les lots ou de nouvelles données.","If group and batch coincide, model columns are collinear. Visual separation cannot identify its source; groups represented within batches or new data are needed."]},{"q":["Pourquoi projeter les dix souris de test avec la moyenne et l'écart-type des trente souris d'apprentissage ?","Why project the ten test mice using the mean and SD of the thirty training mice?"],"a":[["Pour maintenir une transformation gelée avant le test","To preserve a transformation frozen before testing"],["Pour augmenter artificiellement la corrélation","To artificially increase correlation"],["Pour rendre le test externe","To make the test external"]],"correct":0,"why":["La transformation est apprise sur le train, puis appliquée au test. Ce test interne ne devient pas une cohorte externe ; la présence de deux mesures chez un même animal ne valide pas non plus une prédiction PK.","The transformation is learned in training, then applied to test. Internal holdout does not become an external cohort; two measurements in one animal do not validate PK prediction."]},{"q":["Le nuage CYP3A11–C14.0 permet-il de conclure que CYP3A11 détermine la clairance d'un médicament ?","Does the CYP3A11–C14.0 scatter plot establish that CYP3A11 determines drug clearance?"],"a":[["Oui, car les deux couches sont appariées","Yes, because the two layers are paired"],["Non : il manque une mesure PK et un plan pour tester le mécanisme","No: PK measurements and a design to test the mechanism are missing"],["Oui, si on sélectionne les dix animaux de test","Yes, if the ten test animals are selected"]],"correct":1,"why":["L'appariement permet une association entre deux mesures. Il ne démontre ni causalité, ni activité enzymatique fonctionnelle, ni validité d'une covariable PK. Il faut des observations PK et une validation adaptée.","Pairing supports association between two measurements. It does not establish causality, functional enzyme activity or PK covariate validity. PK observations and appropriate validation are needed."]}]}
  ];
  const guidance=[[[["Identifier l’unité biologique","Identify the biological unit"],["Suivez les traits reliant chaque lignée. Combien d’unités indépendantes observez-vous ?","Follow the lines connecting each cell line. How many independent units do you see?"],["Deux mesures issues d'une même lignée partagent une source de variation.","Two assays from the same cell line share a source of variation."]],[["Contrôler les entrées","Check the inputs"],["Ouvrez les comptages exacts ; distinguez le tableau d'échantillons et la matrice des gènes.","Open the exact counts; distinguish the sample sheet from the gene matrix."],["Les identifiants et le type de mesure déterminent les modèles admissibles.","Identifiers and measurement type determine eligible models."]],[["Distinguer exploration et inférence","Distinguish exploration from inference"],["Le graphique apparié montre des variations visibles ; imaginez une projection de tous les gènes. Qu'est-ce qu'une projection ne teste pas ?","The paired plot shows visible variation; imagine a projection across all genes. What does a projection not test?"],["Une projection décrit une structure ; un contraste a son propre modèle et son incertitude.","A projection describes structure; a contrast has its own model and uncertainty."]],[["Contrôler les découvertes","Control discoveries"],["Modifiez le seuil BH : comparez le nombre de gènes déclarés à 0,01, 0,05 et 0,10.","Change the BH threshold: compare the discovery counts at 0.01, 0.05 and 0.10."],["L'amplitude et la multiplicité répondent à deux questions différentes.","Effect size and multiplicity address different questions."]]],[[["Aligner les couches","Align the layers"],["Un point représente une souris : repérez les deux variables et leurs unités.","One point represents a mouse: identify the two variables and their units."],["L'ordre des colonnes n'est pas un identifiant.","Column order is not an identifier."]],[["Comparer les échelles","Compare scales"],["Comparez l'échelle de l'expression et le pourcentage lipidique ; ouvrez les scores standardisés.","Compare the expression scale and fatty-acid percentage; open the standardized scores."],["Une couche de grande variance peut dominer une représentation.","A high-variance layer may dominate a representation."]],[["Choisir la question","Choose the question"],["Le nuage montre deux variables ; réfléchissez à la différence entre résumer une structure et prédire un groupe.","The scatter shows two variables; distinguish summarizing structure from predicting a group."],["Une méthode supervisée utilise les étiquettes.","A supervised method uses labels."]],[["Évaluer sans fuite","Evaluate without leakage"],["Sélectionnez les trente animaux du train puis les dix du test ; comparez leur rôle.","Select the thirty training animals then the ten test animals; compare their roles."],["Une signature choisie sur tous les animaux n'est pas un test indépendant.","A signature chosen on all animals is not an independent test."]]],[[["Lire un seuil, pas une nouvelle analyse","Read a threshold, not a new analysis"],["Changez le seuil BH de 0,05 à 0,01 sur le résultat réel.","Change the BH threshold from 0.05 to 0.01 on the real result."],["Les q-values restent fixes.","Adjusted p-values stay fixed."]],[["Lire un contraste ajusté","Read a fitted contrast"],["Comparez les quatre paires de comptages et le log2FC issu de DESeq2.","Compare the four count pairs and the DESeq2 log2FC."],["Un log2FC positif décrit le sens du contraste.","Positive log2FC describes the contrast direction."]],[["Reconnaître un lot confondu","Recognize confounded batch"],["Dans la simulation, croisez groupes et lots, puis augmentez l'effet du lot.","In the simulation, cross groups and batches, then increase the batch effect."],["L'identifiabilité dépend du plan, pas de la beauté du graphique.","Identifiability depends on design, not on how clear a plot looks."]],[["Distinguer apprentissage et test","Distinguish training and test"],["Affichez les dix souris de test et lisez leurs scores gelés.","Display the ten test mice and read their frozen scores."],["La standardisation est une transformation apprise.","Standardization is a learned transformation."]],[["Formuler une conclusion limitée","Write a bounded conclusion"],["Relisez la provenance et les unités du nuage ; quelle variable manque pour conclure sur la PK ?","Read the scatter provenance and units; what variable is missing for a PK conclusion?"],["Une association entre couches ne mesure pas une clairance.","A cross-layer association does not measure clearance."]]]];
  let selected=0, step=0, answer=-1, hint=false;
  let completed=[0,0,0];
  $: guide=guidance[selected][step];
  $: journey=paths[selected];
  $: question=journey.steps[step];
  $: finished=step===journey.steps.length;
  /** @param {number} index */
  function start(index){ selected=index; step=completed[index]; answer=-1; hint=false; }
  function restart(){ completed=[...completed]; completed[selected]=0; step=0; answer=-1; hint=false; }
  function next(){ if(answer!==question.correct)return; completed=[...completed]; completed[selected]=step+1; step+=1; answer=-1; hint=false; }
</script>
<svelte:head><title>Mo Game — MultiOmics</title></svelte:head>
<a class="back" href={resolve('multiomics/')}>{t('Retour à MultiOmics','Back to MultiOmics')}</a>
<h1>Mo Game</h1>
<p class="lede">{t('Trois enquêtes guidées : observer, manipuler, décider et interpréter les résultats omiques.','Three guided investigations: observe, manipulate, decide and interpret omics results.')}</p>
<p>{t('Cas pédagogiques sur données publiques. Les figures présentent des mesures et résultats qualifiés ; aucune réestimation n’est faite dans le navigateur.','Educational cases on public data. Figures show qualified measurements and results; no model is refitted in the browser.')}</p>
<div class="journeys">
{#each paths as path,i}
  <button class:active={selected===i} aria-pressed={selected===i} onclick={()=>start(i)}><strong>{i===2?t('Interprétation','Interpretation'):path.name}</strong><span>{t(path.title[0],path.title[1])}</span><small>{completed[i]}/{path.steps.length}</small></button>
{/each}
</div>
<section class="mission" aria-labelledby="mission-title">
  <div class="study" data-testid="mo-game-study">
    {#if selected===0}
      <h2>Airway · GSE52778</h2>
      <p>{t('Vrai plan expérimental : quatre lignées de cellules, chacune mesurée sans et avec dexaméthasone.','Real experimental design: four cell lines, each measured without and with dexamethasone.')}</p>
      <div class="pair-grid">
        {#each [1,2,3,4] as donor}
          <div class="pair"><span>{t('Lignée','Cell line')} {donor}</span><span>{t('Sans traitement','Untreated')}</span><span aria-hidden="true">↔</span><span>{t('Dexaméthasone','Dexamethasone')}</span></div>
        {/each}
      </div>
      <p>{t('8 mesures appariées, 17 199 gènes conservés après filtrage de référence. Le schéma représente le plan réel, pas les intensités mesurées.','8 paired assays, 17,199 genes retained after reference filtering. The diagram represents the real design, not measured intensities.')}</p>
      <a href="https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc=GSE52778" target="_blank" rel="noopener noreferrer">{t('Source publique GSE52778','Public GSE52778 source')}</a> · <a href="https://github.com/rberrah/MultiOmics/blob/adebb86ffd11bdd89582d18bb07fd56cf22dd1f3/docs/multiomics/PUBLIC_AIRWAY_SITE_R_REPLAY.md" target="_blank" rel="noopener noreferrer">{t('Qualification DESeq2','DESeq2 qualification')}</a>
    {:else if selected===1}
      <h2>Nutrimouse · mixOmics</h2>
      <p>{t('40 souris, 120 signaux d’expression hépatique et 21 pourcentages d’acides gras. Les deux couches sont appariées par animal.','40 mice, 120 liver expression signals and 21 fatty-acid percentages. The two layers are paired by animal.')}</p>
      <div class="pair-grid"><div class="pair"><span>{t('40 souris','40 mice')}</span><span>{t('Expression · 120','Expression · 120')}</span><span aria-hidden="true">↔</span><span>{t('Lipides · 21','Lipids · 21')}</span></div></div>
      <p>{t('Aucune concentration PK n’est mesurée : ces données ne valident pas une covariable PK.','No PK concentrations are measured: these data do not validate a PK covariate.')}</p>
      <a href="https://github.com/mixOmics-org/mixOmics/blob/ef3e760526623d9e91e945e4b50be48d764efc40/data/nutrimouse.rda" target="_blank" rel="noopener noreferrer">{t('Données originales mixOmics','Original mixOmics data')}</a> · <a href="https://github.com/rberrah/MultiOmics/blob/adebb86ffd11bdd89582d18bb07fd56cf22dd1f3/docs/multiomics/REAL_NUTRIMOUSE_FROZEN_SCORE_PROTOCOL.md" target="_blank" rel="noopener noreferrer">{t('Protocole reproductible','Reproducible protocol')}</a>
    {:else}
      <h2>{t('Mission : relire un rapport omique','Mission: review an omics report')}</h2>
      <p>{t('Votre objectif : distinguer signal, biais et preuve. Deux études publiques et une simulation de lot clairement identifiée.','Your goal: distinguish signal, bias and evidence. Two public studies and one explicitly labeled batch simulation.')}</p>
    {/if}
  </div>
  <div class="mission-progress"><label for="mo-progress">{t('Progression du parcours','Journey progress')} : {completed[selected]}/{journey.steps.length}</label><progress id="mo-progress" max={journey.steps.length} value={completed[selected]}></progress></div>
  {#if !finished && guide}
    <section class="mission-brief" data-testid="mission-brief"><h3>{t(guide[0][0],guide[0][1])}</h3><p><strong>{t('À observer / manipuler :','Observe / manipulate:')}</strong> {t(guide[1][0],guide[1][1])}</p></section>
  {/if}
  {#if selected===2 && step===2}<GameBatchLab />
  {:else if selected===2 && step>=3}<PublicStudyEvidence study="nutrimouse"/>
  {:else}<PublicStudyEvidence study={selected===1?'nutrimouse':'airway'} />{/if}
  <h2 id="mission-title">{journey.name} · {finished?t('Parcours terminé','Journey complete'):t('Étape','Step')+' '+(step+1)+' / '+journey.steps.length}</h2>
  {#if finished}
    <p>{t('Vous avez terminé les décisions de ce parcours. Distinguez observations, méthode, résultats et limites avant de poursuivre.','You completed this journey. Distinguish observations, method, results and limitations before moving on.')}</p>
    <p>{t('Pour appliquer vos décisions, ouvrez le véritable outil. La démo intégrée utilise des données pédagogiques distinctes des études Airway et Nutrimouse.','Apply your decisions in the actual tool. The built-in demo uses educational data distinct from Airway and Nutrimouse.')}</p>
    <a href={resolve('multiomics/tool/')}>{t('Tester une omique (bouton Transcriptomique)','Try one omics layer (Transcriptomics button)')}</a> · <a href={resolve('multiomics/tool/')+'?demo=multi'}>{t('Tester les trois omiques','Try all three omics layers')}</a> · <a href={resolve('multiomics/demo/')}>{t('Voir la démonstration','View the demo')}</a>
    <p><a href={'https://rberrah.github.io/Omics2PK/?lang='+$language} data-sveltekit-reload>{t('Application : relier les omiques à la PK','Application: link omics to PK')}</a></p>
    <p><a href={resolve('multiomics/learn/')}>{t('Revoir la méthodologie','Review the methodology')}</a> · <a href={resolve('multiomics/practice/')}>{t('S’entraîner','Practice')}</a></p>
    <button onclick={restart}>{t('Recommencer ce parcours','Restart this journey')}</button>
  {:else}
    <h3>{t(question.q[0],question.q[1])}</h3>
    <div class="answers">
      {#each question.a as item,i}<button aria-pressed={answer===i} onclick={()=>answer=i}>{t(item[0],item[1])}</button>{/each}
    </div>
    {#if answer>=0}
      <p role="status"><strong>{answer===question.correct?t('Correct.','Correct.'):t('À revoir.','Try again.')}</strong> {t(question.why[0],question.why[1])}</p>
    {/if}
    <button type="button" class="hint" aria-expanded={hint} onclick={()=>hint=!hint}>{t('Un indice','A hint')}</button>
    {#if hint && guide}<p class="hint-box">{t(guide[2][0],guide[2][1])}</p>{/if}
    <button class="next" disabled={answer!==question.correct} onclick={next}>{t('Continuer','Continue')}</button>
  {/if}
</section>
<style>
.back{display:inline-flex;align-items:center;min-height:44px}
h1{font-size:clamp(2rem,6vw,4rem);margin:.5rem 0}.lede{font-size:1.2rem}
.journeys{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,260px),1fr));gap:1rem;margin:2rem 0}
button{font:inherit;color:var(--text-primary);background:var(--bg-secondary);border:1px solid var(--border-strong);border-radius:8px;min-height:44px;padding:1rem;text-align:left;cursor:pointer}
button:focus-visible,a:focus-visible{outline:2px solid var(--accent-pk);outline-offset:3px}
button[aria-pressed=true]{border:2px solid var(--accent-pk);box-shadow:inset 0 0 0 1px var(--accent-pk)}
.journeys button{display:grid;gap:.5rem}.mission{border-top:1px solid var(--border-strong);padding:1.5rem 0 3rem;max-width:900px}
.study{padding:1rem;border:1px solid var(--border-strong);border-radius:8px;margin-bottom:1.5rem}.pair-grid{display:grid;gap:.5rem}.pair{display:flex;flex-wrap:wrap;align-items:center;gap:.5rem;padding:.5rem;border:1px solid var(--border-subtle);border-radius:6px}.pair span:first-child{font-weight:700;min-width:5rem}.pair span:nth-child(2),.pair span:last-child{padding:.35rem .5rem;background:var(--bg-secondary);border:1px solid var(--border-strong);border-radius:5px}.answers{display:grid;gap:.75rem}.next{margin-top:1rem}.next:disabled{opacity:.55;cursor:not-allowed}
.mission-progress{display:grid;gap:.3rem;margin-bottom:1rem}.mission-progress progress{width:100%;height:12px;accent-color:var(--accent-pk)}.mission-brief,.hint-box{border:1px solid var(--border-strong);border-radius:8px;background:var(--bg-secondary);padding:1rem}.hint{margin-top:1rem;margin-right:.5rem}
</style>
